import React, { useState } from 'react';
import { sendEnquiry } from '../services/api';
import { useAuth } from '../context/AuthContext';
import { X, PhoneCall, Send, CheckCircle2 } from 'lucide-react';
import styles from './EnquiryModal.module.css';

export default function EnquiryModal({ property, onClose, initialMode = 'enquire' }) {
  const { user } = useAuth();
  const [mode, setMode] = useState(initialMode); // 'enquire' | 'callback'
  const [form, setForm] = useState({
    name:    user?.name    || '',
    email:   user?.email   || '',
    phone:   user?.phone   || '',
    message: initialMode === 'callback'
      ? `Request callback for "${property?.title || 'this property'}".`
      : `I am interested in "${property?.title || 'this property'}". Please get in touch with me.`,
  });
  const [loading, setLoading] = useState(false);
  const [sent,    setSent]    = useState(false);
  const [error,   setError]   = useState('');

  const isCallback = mode === 'callback';

  const handleModeChange = (newMode) => {
    setMode(newMode);
    setError('');
    setForm((f) => ({
      ...f,
      message: newMode === 'callback'
        ? `Request callback for "${property?.title || 'this property'}".`
        : `I am interested in "${property?.title || 'this property'}". Please get in touch with me.`,
    }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');

    // Ensure at least name and a phone or email is provided
    if (!form.phone && !form.email) {
      setError('Please provide a phone number or email address so we can reach you.');
      return;
    }

    setLoading(true);
    try {
      await sendEnquiry({
        propertyId: property?.id || property?._id,
        propertyTitle: property?.title || '',
        propertyImage: property?.image || (property?.images?.[0]) || '',
        name: form.name.trim(),
        email: form.email.trim(),
        phone: form.phone.trim(),
        mobile: form.phone.trim(), // also send as mobile for strict backends
        message: form.message.trim(),
        isCallback,
      });
      setSent(true);
    } catch (err) {
      console.error('[Enquiry Submission Error]', err);
      const serverMsg = err.response?.data?.message || err.message;
      setError(serverMsg && serverMsg !== 'Network Error' ? serverMsg : 'Failed to send. Please check that the backend server is running and try again.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className={styles.overlay} onClick={(e) => { if (e.target === e.currentTarget) onClose(); }}>
      <div className={styles.modal}>
        {/* Header */}
        <div className={styles.header}>
          <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
            <h2 className={styles.title}>
              {isCallback ? 'Request a Callback' : 'Send Enquiry'}
            </h2>
          </div>
          <button className={styles.closeBtn} onClick={onClose} aria-label="Close">
            <X size={20} />
          </button>
        </div>

        {/* Mode switcher tabs */}
        <div style={{ display: 'flex', borderBottom: '1px solid var(--border)', background: 'var(--surface-muted)' }}>
          <button
            type="button"
            onClick={() => handleModeChange('enquire')}
            style={{
              flex: 1,
              padding: '10px 14px',
              fontSize: '13px',
              fontWeight: 700,
              border: 'none',
              background: !isCallback ? '#fff' : 'transparent',
              color: !isCallback ? 'var(--primary)' : 'var(--text-secondary)',
              borderBottom: !isCallback ? '2px solid var(--primary)' : 'none',
              cursor: 'pointer',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              gap: 6,
            }}
          >
            <Send size={14} />
            Send Enquiry
          </button>
          <button
            type="button"
            onClick={() => handleModeChange('callback')}
            style={{
              flex: 1,
              padding: '10px 14px',
              fontSize: '13px',
              fontWeight: 700,
              border: 'none',
              background: isCallback ? '#fff' : 'transparent',
              color: isCallback ? '#b45309' : 'var(--text-secondary)',
              borderBottom: isCallback ? '2px solid #b45309' : 'none',
              cursor: 'pointer',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              gap: 6,
            }}
          >
            <PhoneCall size={14} />
            Request Callback
          </button>
        </div>

        {/* Property snippet */}
        {property && (
          <div className={styles.propSnippet}>
            <img
              src={property.image || (property.images?.[0]) || 'https://images.unsplash.com/photo-1600585154340-be6161a56a0c?w=400&q=70'}
              alt={property.title}
              className={styles.propImg}
            />
            <div>
              <div className={styles.propTitle}>{property.title}</div>
              <div className={styles.propPrice}>{property.price}</div>
              <div className={styles.propLoc}>{property.location || property.city}</div>
            </div>
          </div>
        )}

        {sent ? (
          <div className={styles.success}>
            <div className={styles.successIcon} style={{ color: '#16a34a' }}>
              <CheckCircle2 size={54} />
            </div>
            <div className={styles.successTitle}>
              {isCallback ? 'Callback Requested!' : 'Enquiry Sent!'}
            </div>
            <div className={styles.successSub}>
              {isCallback
                ? 'Our advisor will call you back shortly on your phone number.'
                : 'Your enquiry has been received and listed in the admin dashboard. We will get in touch shortly.'}
            </div>
            <button className={styles.doneBtn} onClick={onClose}>Done</button>
          </div>
        ) : (
          <form className={styles.form} onSubmit={handleSubmit}>
            {error && <div className={styles.error}>{error}</div>}

            <div className={styles.row}>
              <div className={styles.field}>
                <label className={styles.label}>Full Name *</label>
                <input
                  type="text"
                  className={styles.input}
                  placeholder="Your Name"
                  value={form.name}
                  onChange={(e) => setForm((f) => ({ ...f, name: e.target.value }))}
                  required
                />
              </div>
              <div className={styles.field}>
                <label className={styles.label}>
                  Phone Number {isCallback ? '*' : ''}
                </label>
                <input
                  type="tel"
                  className={styles.input}
                  placeholder="10-digit mobile"
                  value={form.phone}
                  onChange={(e) => setForm((f) => ({ ...f, phone: e.target.value }))}
                  required={isCallback}
                />
              </div>
            </div>

            <div className={styles.field}>
              <label className={styles.label}>
                Email Address {!isCallback ? '*' : '(Optional)'}
              </label>
              <input
                type="email"
                className={styles.input}
                placeholder="your.email@example.com"
                value={form.email}
                onChange={(e) => setForm((f) => ({ ...f, email: e.target.value }))}
                required={!isCallback}
              />
            </div>

            {!isCallback && (
              <div className={styles.field}>
                <label className={styles.label}>Message</label>
                <textarea
                  rows={3}
                  className={styles.textarea}
                  placeholder="I am interested in this property..."
                  value={form.message}
                  onChange={(e) => setForm((f) => ({ ...f, message: e.target.value }))}
                  required
                />
              </div>
            )}

            <button
              type="submit"
              className={styles.submitBtn}
              style={{
                background: isCallback ? '#b45309' : 'var(--primary)',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                gap: 8,
              }}
              disabled={loading}
            >
              {loading ? (
                'Submitting…'
              ) : isCallback ? (
                <>
                  <PhoneCall size={16} /> Request Callback
                </>
              ) : (
                <>
                  <Send size={16} /> Send Enquiry
                </>
              )}
            </button>
          </form>
        )}
      </div>
    </div>
  );
}
